// NOTE : dummyjson.com est une API de mock qui n'effectue pas de validation
// des types de données. Elle accepte des valeurs invalides et retourne 201.
// Ce test documente ce comportement et sert de référence pour une vraie API.

// Test 1 : Comportement réel de dummyjson — retourne 201 même avec données invalides
pm.test("[dummyjson] Retourne 201 (pas de validation des types)", function () {
    pm.response.to.have.status(201);
});

// Test 2 : La réponse est du JSON
pm.test("La réponse est au format JSON", function () {
    pm.response.to.be.json;
});

// Test 3 : Le corps contient les champs envoyés (sans validation)
pm.test("Le corps contient le titre envoyé", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("title", "Produit Test");
});

// Test 4 : Le prix invalide est accepté tel quel (comportement mock)
pm.test("[dummyjson] Le prix invalide est accepté sans erreur (API mock)", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("price", "pas-un-nombre");
});

// Test 5 : Temps de réponse
pm.test("Temps de réponse inférieur à 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

