// Test 1 : Vérifier que le statut HTTP est 404 Not Found
pm.test("Statut HTTP est 404 Not Found", function () {
    pm.response.to.have.status(404);
});

// Test 2 : Vérifier que la réponse est du JSON
pm.test("La réponse est au format JSON", function () {
    pm.response.to.be.json;
});

// Test 3 : Vérifier que le corps contient un message d'erreur explicite
pm.test("La réponse contient un message d'erreur explicite", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("message");
    pm.expect(json.message).to.be.a("string").and.not.empty;
});

// Test 4 : Vérifier que le message mentionne l'ID du produit introuvable
pm.test("Le message d'erreur mentionne l'ID '99999'", function () {
    const json = pm.response.json();
    pm.expect(json.message).to.include("99999");
});

// Test 5 : Vérifier le temps de réponse
pm.test("Temps de réponse inférieur à 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});
